function cleanButtonArrows(root=document){
  if(!root)return;
  for(const button of root.querySelectorAll('button')){
    button.querySelectorAll('.arrow,.tile-arrow,.diagonal').forEach(node=>node.remove());
    for(const svg of button.querySelectorAll('svg.icon'))if(svg.innerHTML.includes('M5 12h14'))svg.remove();
    const walker=document.createTreeWalker(button,NodeFilter.SHOW_TEXT);
    const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
    for(const node of nodes){const text=node.nodeValue.replace(/[\u2197\u2198\u2192]/g,'').trimEnd();if(text!==node.nodeValue)node.nodeValue=text;}
  }
}

function bindSwipes(){
  for(const row of document.querySelectorAll('[data-swipe]:not([data-swipe-bound])')){
    row.dataset.swipeBound='true';
    const content=row.querySelector('.swipe-content');
    let startX=0,startY=0,offset=0,dragging=false;
    const finish=()=>{if(!startX)return;content.style.transform='';row.classList.toggle('open',dragging&&offset>44);if(dragging){row.dataset.swipeBlock='1';setTimeout(()=>delete row.dataset.swipeBlock,350);}startX=0;dragging=false;offset=0;};
    content.addEventListener('pointerdown',e=>{if(e.button!==0)return;startX=e.clientX;startY=e.clientY;offset=0;dragging=false;row.classList.add('swiping');content.setPointerCapture?.(e.pointerId);});
    content.addEventListener('pointermove',e=>{if(!startX)return;const dx=e.clientX-startX,dy=e.clientY-startY;if(!dragging&&dx>7&&Math.abs(dx)>Math.abs(dy))dragging=true;if(!dragging)return;offset=Math.min(82,Math.max(0,dx));content.style.transform=`translateX(${offset}px)`;});
    content.addEventListener('pointerup',()=>{row.classList.remove('swiping');finish();});
    content.addEventListener('pointercancel',()=>{row.classList.remove('swiping');finish();});
  }
}

function bindPairingSwipes(){
  const close=row=>{row.classList.remove('open');row.querySelector('.pairing-delete').disabled=true;};
  for(const row of document.querySelectorAll('.pairing-swipe:not([data-bound])')){
    row.dataset.bound='1';const card=row.querySelector('.folder'),del=row.querySelector('.pairing-delete');
    let start=null,offset=0,moved=false,base=0,blocked=false;
    row.addEventListener('click',e=>{if(blocked||(row.classList.contains('open')&&!e.target.closest('.pairing-delete'))){e.preventDefault();e.stopImmediatePropagation();if(!blocked)close(row);}},true);
    card.addEventListener('dragstart',e=>e.preventDefault());
    card.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY};base=row.classList.contains('open')?76:0;offset=base;moved=false;});
    card.addEventListener('pointermove',e=>{
      if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;
      if(!moved){if(Math.abs(dy)>8&&Math.abs(dy)>=Math.abs(dx)){start=null;return;}if(Math.abs(dx)<8)return;moved=true;card.setPointerCapture(e.pointerId);for(const other of document.querySelectorAll('.pairing-swipe.open'))if(other!==row)close(other);row.classList.add('swiping');}
      offset=Math.max(0,Math.min(76,base-dx));card.style.transform=`translateX(${-offset}px)`;
    });
    const finish=cancel=>{if(!start)return;start=null;row.classList.remove('swiping');card.style.transform='';if(moved){const open=!cancel&&offset>32;row.classList.toggle('open',open);del.disabled=!open;blocked=true;setTimeout(()=>blocked=false,350);}moved=false;};
    card.addEventListener('pointerup',()=>finish(false));card.addEventListener('pointercancel',()=>finish(true));
  }
}

async function dispatchMaterial(text,assetIds){const mode=assetIds.length&&/复刻|仿妆|照着|参考妆/.test(text)?'recreate':'assistant';closeModal();await startTask(text,'',mode,assetIds);}

function idb(store,mode,fn){return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode);let request;try{request=fn(tx.objectStore(store));}catch(e){reject(e);return;}tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('保存失败'));});}
async function openDB(){db=await new Promise((resolve,reject)=>{const r=indexedDB.open('tutu-simulation-v06',1);r.onupgradeneeded=()=>{r.result.createObjectStore('kv');r.result.createObjectStore('assets');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function save(){try{await idb('kv','readwrite',s=>s.put(state,'state'));}catch(e){toast('本地存储未成功，请检查浏览器空间后重试。');throw e;}}
async function commit(fn){const before=structuredClone(state);fn();try{await save();}catch(e){state=before;throw e;}}
