function field(label,name,value='',options={}){return `<label class="field"><span>${label}</span>${options.area?`<textarea name="${name}" maxlength="${options.max||2000}" placeholder="${esc(options.placeholder||'')}">${esc(value)}</textarea>`:options.select?`<select name="${name}">${options.select.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${value===id?'selected':''}>${esc(text)}</option>`;}).join('')}</select>`:`<input name="${name}" value="${esc(value)}" maxlength="${options.max||100}" placeholder="${esc(options.placeholder||'')}" ${options.required?'required':''}>`}</label>`;}
