function folder(p){const expanded=state.ui.expanded===p.id;return `<article class="folder ${expanded?'is-expanded':''}" data-folder="${esc(p.id)}"><div class="folder-top"><button class="folder-title" data-a="pairing" data-id="${esc(p.id)}">#${esc(p.name)}</button><button class="expand" data-a="expand" data-id="${esc(p.id)}" aria-expanded="${expanded}"><img class="pair-arrow" src="./assets/icons/arrow.svg" alt="">点击${expanded?'收起':'展开'}</button></div><div class="folder-body">${swatches(p)}${expanded?`<div class="expanded-products">${miniProduct(p.blush)}${miniProduct(p.lip)}</div>${photos(p)}`:''}<div class="folder-foot"><div class="pairing-tags">${p.regular?'<span class="regular-label">常用搭配</span>':''}<span>#${esc(p.mood||'我的唇颊搭配')}</span></div><button class="detail-link" data-a="pairing" data-id="${esc(p.id)}">搭配详情</button></div></div></article>`;}

