function pairingsPage(){queueMicrotask(bindPairingSwipes);const f=state.ui.filter==='regular'?'regular':'all';const rows=state.pairings.filter(p=>(f==='all'||p.regular)&&product(p.blush)&&product(p.lip));const filters=[['regular','常用'],['all','全部']].map(([k,v])=>btn(v,'filter',`pill ${f===k?'active':''}`,`data-id="${k}"`)).join('');const groups=new Map();for(const p of rows){const label=`${p.blushToneLabel||product(p.blush)?.tone||'待确认'}腮红 × ${p.lipToneLabel||product(p.lip)?.tone||'待确认'}口红`;if(!groups.has(label))groups.set(label,[]);groups.get(label).push(p);}return `<div class="section-head pairings-heading"><h1>唇颊搭配</h1><div class="pills pairing-filter-pills">${btn('+添加搭配','record','pill add-pairing','aria-label="添加唇颊搭配"')}${filters}</div></div>${[...groups].map(([label,items])=>`<section class="tone-group">${items.map(p=>`<div class="pairing-swipe"><button class="pairing-delete" data-a="delete-pairing" data-id="${esc(p.id)}" aria-label="删除搭配 ${esc(p.name)}" disabled>删除</button>${folder(p)}</div>`).join('')}</section>`).join('')||empty('还没有这类搭配','把想试的组合记下来，下次不用重新想。','record','记录一套搭配')}`;}
function productsPage(){const c=state.ui.category;const rows=active().filter(p=>p.category===c);return `<div class="pills product-pills">${[['blush','腮红'],['lip','口红']].map(([k,n])=>btn(`${n}（${active().filter(p=>p.category===k).length}）`,'category',`pill ${c===k?'active':''}`,`data-id="${k}"`)).join('')}</div>${rows.length?`<div class="product-grid">${rows.map(p=>`<button class="product-cell" data-a="product" data-id="${esc(p.id)}">${art(p)}<strong>${esc(p.shade||p.name)}</strong><small>${esc(p.brand||'未填写品牌')}</small></button>`).join('')}</div>`:`<div class="product-empty">${empty('这一格，留给你的颜色','拍下产品，确认色号后就能加入产品库。','capture','添加产品')}</div>`}`;}
